import React, { useState } from 'react';
import { createCliente } from '../api/ClienteApi'; // Importa a função de criação

const CreateCliente = ({ onCreate }) => {
  const [nome, setNome] = useState('');
  const [email, setEmail] = useState('');
  const [telefone, setTelefone] = useState('');
  const [error, setError] = useState('');

  const handleSubmit = (event) => {
    event.preventDefault();

    const cliente = { nome, email, telefone };

    createCliente(cliente) // Usando a função da API para criar o cliente
      .then(response => {
        onCreate(response.data); // Atualiza a lista de clientes no componente pai
        setNome('');
        setEmail('');
        setTelefone('');
      })
      .catch(err => {
        setError('Erro ao criar cliente');
        console.error(err);
      });
  };

  return (
    <div>
      <h2>Criar Cliente</h2>
      {error && <p>{error}</p>}
      <form onSubmit={handleSubmit}>
        <div>
          <label>Nome:</label>
          <input type="text" value={nome} onChange={(e) => setNome(e.target.value)} required />
        </div>
        <div>
          <label>Email:</label>
          <input type="email" value={email} onChange={(e) => setEmail(e.target.value)} required />
        </div>
        <div>
          <label>Telefone:</label>
          <input type="text" value={telefone} onChange={(e) => setTelefone(e.target.value)} required />
        </div>
        <button type="submit">Criar Cliente</button>
      </form>
    </div>
  );
};

export default CreateCliente;
